SELECT Ensembl, "Secretome location" FROM proteinatlas WHERE Ensembl IS NOT NULL AND Ensembl IN (
  'ENSG00000118308','ENSG00000130038','ENSG00000127191','ENSG00000108849','ENSG00000107201','ENSG00000137673','ENSG00000136244','ENSG00000155659','ENSG00000105398','ENSG00000156234','ENSG00000206047','ENSG00000240247'
)

SELECT "ENSG ID", 1 AS has_ia FROM blood_immunoassay_concentration WHERE "ENSG ID" IN (
  'ENSG00000118308','ENSG00000130038','ENSG00000127191','ENSG00000108849','ENSG00000107201','ENSG00000137673','ENSG00000136244','ENSG00000155659','ENSG00000105398','ENSG00000156234','ENSG00000206047','ENSG00000240247'
) GROUP BY "ENSG ID"
